import{_ as e,o as a,c as r,aj as i}from"./chunks/framework.BwH0p-pt.js";const h=JSON.parse('{"title":"Attribute Input Type","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/attribute/attribute-input.md","filePath":"2.1/attribute/attribute-input.md","lastUpdated":1779693222000}'),s={name:"2.1/attribute/attribute-input.md"};function o(d,t,n,p,l,u){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="attribute-input-type" tabindex="-1">Attribute Input Type <a class="header-anchor" href="#attribute-input-type" aria-label="Permalink to &quot;Attribute Input Type&quot;">​</a></h1><p>Attributes can have different input types that determine not only how you enter the values for the attribute, but also how shoppers can select attributes in the case of options, or enter values.</p><p>Product Attributes are a set of characteristics that define a particular product or a group of goods. This means size, color, flavor, package type, etc. constitute attributes. Product attributes are not just about the general description of a product, but they speak about the value of products that makes it unique.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td>Text</td><td>A single-line input field for text.</td></tr><tr><td>Text Area</td><td>A multiple-line input field for entering paragraphs of text, such as a product description.</td></tr><tr><td>Boolean</td><td>Displays a switch to toggle between Yes and No.</td></tr><tr><td>Select</td><td>Displays a dropdown list of values that accepts a single selection. Supports <strong>Swatch Types</strong> (Color, Image, Text) for visual option display.</td></tr><tr><td>Multi Select</td><td>Displays a drop-down list of values that accepts multiple selections. Supports <strong>Swatch Types</strong> (Color, Image, Text) for visual option display.</td></tr><tr><td>Date</td><td>Displays a date value in the preferred format.</td></tr><tr><td>Date Time</td><td>Displays a date and time value in the preferred format and time zone.</td></tr><tr><td>Image</td><td>This is used to show the image.</td></tr><tr><td>Gallery</td><td>A Gallery attribute that allows managing and displaying multiple images and <strong>videos</strong> per product, enhancing the product media experience.</td></tr><tr><td>File</td><td>File attributes refers to a specific type of attributes that allows you to associate files with the product.</td></tr><tr><td>Checkbox</td><td>It represents a state or option that can be toggled.</td></tr><tr><td>Price</td><td>This input type is used to create price fields that are in addition to the predefined attributes: Prices.</td></tr></tbody></table><h2 id="swatch-types-new-in-v2-0" tabindex="-1">Swatch Types (New in v2.0) <a class="header-anchor" href="#swatch-types-new-in-v2-0" aria-label="Permalink to &quot;Swatch Types (New in v2.0)&quot;">​</a></h2><p><strong>Select</strong> and <strong>Multiselect</strong> attributes now support visual swatch types:</p><table tabindex="0"><thead><tr><th>Swatch Type</th><th>Description</th></tr></thead><tbody><tr><td>Dropdown</td><td>Standard dropdown selection (default behavior)</td></tr><tr><td>Color</td><td>Displays color swatches — each option shows a colored box</td></tr><tr><td>Image</td><td>Displays image thumbnails — each option shows a small image</td></tr><tr><td>Text</td><td>Displays text labels as styled visual swatches</td></tr></tbody></table><p>Swatch types are configured when creating or editing a Select/Multiselect attribute. See <a href="./product-attribute.html#swatch-types">Create Product Attribute</a> for setup instructions.</p>',8)])])}const b=e(s,[["render",o]]);export{h as __pageData,b as default};
